from more_itertools import ichunked

def test_basic():
    assert [list(c) for c in ichunked(range(6), 3)] == [[0, 1, 2], [3, 4, 5]]

def test_print_ichunked():
    with open('tests/test_more.py') as f:
        text = f.read()

    start = text.find('class IchunkedTests')
    end = text.find('class ', start + 1)
    assert False, text[start:end]

import pytest
import more_itertools as mi

def test_chunked_zero():
    try:
        res = list(mi.chunked([1, 2, 3], 0))
        print("chunked zero:", res)
    except Exception as e:
        print("chunked zero raised:", type(e), e)

def test_ichunked_zero():
    try:
        res = list(mi.ichunked([1, 2, 3], 0))
        print("ichunked zero:", res)
    except Exception as e:
        print("ichunked zero raised:", type(e), e)
    assert False

import more_itertools as mi

def test_chunked():
    try:
        print("chunked([1], 0):", list(mi.chunked([1], 0)))
    except Exception as e:
        print("chunked([1], 0) raised:", type(e), e)

    try:
        print("chunked([], 0):", list(mi.chunked([], 0)))
    except Exception as e:
        print("chunked([], 0) raised:", type(e), e)
    assert False

import more_itertools as mi

def test_ichunked_none():
    try:
        res = [list(c) for c in mi.ichunked([1, 2, 3], None)]
        print("ichunked none:", res)
    except Exception as e:
        print("ichunked none raised:", type(e), e)

    try:
        res = list(mi.chunked([1, 2, 3], None))
        print("chunked none:", res)
    except Exception as e:
        print("chunked none raised:", type(e), e)
    assert False
